/**
 * QR code drawn from the SVG stroke generated by the server (`qr.stroke`):
 * no libraries in the client nor `data:` URI. `size` is the side in modules
 * including the margin; the stroke uses `currentColor` over `bg-card`.
 *
 * @author Pablo Contreras
 * @since 2026/10/01
 */
export function UIQrCode({
  size,
  stroke,
  label,
}: {
  size: number
  stroke: string
  label: string
}): React.JSX.Element {
  return (
    <svg
      role="img"
      aria-label={label}
      viewBox={`0 0 ${size} ${size}`}
      shapeRendering="crispEdges"
      className="size-48 rounded-2xl bg-card text-foreground"
    >
      <path d={stroke} className="fill-current" />
    </svg>
  )
}
